function setBusy(value,label='인물을 오리고 있어요'){busy=value;$('busy').hidden=!value;$('busy-label').textContent=label;renderControls();}
function setStep(value){if(busy)return;if(value!=='camera')stopCamera();step=value;if(value!=='camera')selected=null;if(value==='camera'){$('camera-tools').hidden=false;}render();if(value==='finish')schedulePreview();}
