function renderBackgrounds(){const root=$('background-grid');root.replaceChildren();for(const b of backgrounds){const button=document.createElement('button');button.className='background-card'+(cut().background===b.id?' active':'');button.type='button';button.setAttribute('aria-label',`${b.name} 배경 선택`);button.setAttribute('aria-pressed',String(cut().background===b.id));button.disabled=busy||settings.lockBackground;const wrap=document.createElement('span');wrap.className='image-wrap';const image=document.createElement('img');image.src=b.url;image.alt='';wrap.append(image);const title=document.createElement('strong');title.textContent=b.name;button.append(wrap,title);button.onclick=()=>mutate(()=>{const targets=$('all-backgrounds').checked?project.cuts:[cut()];for(const c of targets)c.background=b.id;});root.append(button);}$('background-count').textContent=`${backgrounds.length}가지 배경`;$('background-fit').value=cut().fit;}
async function render(){syncFields();const version=++renderVersion;document.getElementById("full-preview-section").hidden=step!=='finish';const stageTitles={background:'상상 속으로 떠나볼까요',camera:'우리의 순간을 담아요',edit:'스티커처럼 자유롭게',finish:'반짝이는 사진을 완성해요'};$('cut-label').textContent=`${active+1}번째 컷`;$('stage-title').textContent=stageTitles[step];$('camera-guide').textContent=`${active+1}번째 컷을 찍어요. 카메라를 보고 포즈를 취해요.`;$('next-cut').textContent=active+1<(project.count||4)?`${active+2}번째 컷 만들기`:'전체 사진 확인하기';$('finish-example').hidden=!project.cuts.slice(0,project.count||4).some(c=>c.items.some(i=>i.example));document.querySelectorAll('[data-step]').forEach(b=>{const is=b.dataset.step===step;b.classList.toggle('active',is);if(is)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});for(const s of ['background','camera','edit','finish'])$(`${s}-tools`).hidden=s!==step;$('scene-background').textContent=backgrounds.find(b=>b.id===cut().background)?.name||'나만의 배경';$('example-tag').hidden=!cut().items.some(i=>i.example);$('scene-tip').textContent=step==='camera'?'촬영 후 인물만 오려서 붙여요':step==='edit'?'스티커를 누르고 움직여 보세요':'사진 속 우리를 이 배경에 붙여요';$('scene-tip').hidden=busy||step==='finish';$('mission').textContent=settings.customMissions[active]||MISSIONS[active];$('mission').hidden=!settings.mission;renderBackgrounds();renderCutButtons();renderControls();renderItemControls();await drawCut($('scene'),cut(),assets,backgrounds,{selected,placeholder:true});if(version!==renderVersion)return;if(step==='finish')schedulePreview();}
function renderCutButtons(){const root=$('cut-grid');root.replaceChildren();project.cuts.slice(0,project.count||4).forEach((c,i)=>{const b=document.createElement('button');b.className='cut-card'+(i===active?' active':'');b.setAttribute('aria-label',`${i+1}번 컷${personItems(c).length?' 편집':' 만들기'}`);b.setAttribute('aria-pressed',String(i===active));b.disabled=busy||running;if(c.items.length){const canvas=document.createElement('canvas');canvas.width=240;canvas.height=180;drawCut(canvas,c,assets,backgrounds).catch(()=>{});b.append(canvas);}else{const text=document.createElement('span');text.textContent=`+ ${i+1} CUT`;b.append(text);}const n=document.createElement('span');n.className='cut-no';n.textContent=String(i+1).padStart(2,'0');b.append(n);b.onclick=()=>{active=i;selected=null;sourceMode='append';replaceTarget=null;if(step==='finish')step='edit';render();};root.append(b);});const n=project.cuts.slice(0,project.count||4).filter(c=>personItems(c).length).length;$('progress').textContent=`${n} / ${project.count||4}`;$('progress-bar').style.width=`${n/(project.count||4)*100}%`;}
function renderControls(){
 document.querySelectorAll('#cut-grid button').forEach(b=>b.disabled=busy||running);document.querySelectorAll('#background-grid button').forEach(b=>b.disabled=busy||running||settings.lockBackground);document.getElementById("all-backgrounds").disabled=busy||running||settings.lockBackground;$('undo').disabled=busy||running||!history.past.length;$('redo').disabled=busy||running||!history.future.length;$('download').disabled=busy||!isComplete(project);$('print-photo').disabled=busy||!isComplete(project);$('save-status').textContent=isComplete(project)?`${project.count||4}컷이 모두 준비됐어요. PNG로 저장하거나 인쇄해 주세요.`:`${project.count||4}컷을 모두 채우면 저장할 수 있어요.`;$('capture').textContent=`${settings.timer}초 후 촬영`;$('auto-capture').textContent=`${project.count||4}컷 연속 촬영`;$('capture').disabled=!stream||busy||running;$('start-camera').hidden=!!stream;$('stop-camera').hidden=!stream;$('switch-camera').disabled=!stream||busy||running;$('auto-capture').disabled=!stream||busy||running;$('stop-capture').hidden=!running;$('photo-input').disabled=busy||running;for(const id of ['go-camera','demo-fill','teacher-open','add-person','retake','clear-cut','next-cut','show-finish','new-group'])$(id).disabled=busy||running;document.querySelectorAll('[data-step]').forEach(b=>b.disabled=busy||running);$('toggle-original').disabled=busy||!personItems(cut()).length;$('toggle-original').textContent=cut().original?'스티커로 돌아가기':'원본 보기';$('background-fit').disabled=busy||settings.lockBackground;$('scene').setAttribute('aria-busy',String(busy));}
function renderItemControls(){const adjustment=normalizeAdjustment(cut().adjustment);for(const name of ['brightness','contrast','saturation']){const control=$(`adjust-${name}`);control.value=adjustment[name];control.disabled=busy||!personItems(cut()).length;$(name+'-value').textContent=adjustment[name]+'%';}$('adjust-reset').disabled=busy||!personItems(cut()).length;const it=item(),a=currentAsset();$('selected-tools').hidden=!it||cut().original;for(const id of ['item-front','item-back','item-center','item-duplicate','item-copy','item-delete','item-size','item-rotation','item-border','item-softness'])$(id).disabled=busy||!it;$('item-softness').disabled=busy||!a?.mask;if(it){$('item-size').value=Math.round(it.scale*100);$('item-rotation').value=it.rotation;$('item-softness').value=Math.round(it.softness*100);$('item-border').checked=it.border;}$('retake').disabled=busy||!personItems(cut()).length;$('brush-open').disabled=busy||!a?.mask;const list=$('item-list');list.replaceChildren();cut().items.forEach((it,i)=>{const b=document.createElement('button');b.className='item-chip'+(selected===it.id?' active':'');b.textContent=it.kind==='person'?`${it.example?'예시':'인물'} ${cut().items.slice(0,i+1).filter(x=>x.kind==='person').length}`:`장식 ${i+1}`;b.disabled=busy;b.onclick=()=>{selected=it.id;render();};list.append(b);});}
function schedulePreview(){clearTimeout(previewTimer);const version=renderVersion;previewTimer=setTimeout(safe(async()=>{const c=await renderProject(project,assets,backgrounds,.28,logo);if(version!==renderVersion){c.width=c.height=0;return;}$('full-preview').replaceChildren(c);$('full-preview-section').hidden=step!=='finish';}),120);}
function stopCamera(){cameraEpoch++;if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}$('camera').srcObject=null;$('camera').hidden=true;renderControls();}
async function startCamera(){stopCamera();const request=++cameraEpoch;try{if(!navigator.mediaDevices?.getUserMedia)throw Error('HTTPS 또는 지원 브라우저에서 열어 주세요. 사진 불러오기도 사용할 수 있어요.');const pendingStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:facing},width:{ideal:1280},height:{ideal:960},aspectRatio:{ideal:4/3}},audio:false});if(request!==cameraEpoch||document.hidden||step!=='camera'){pendingStream.getTracks().forEach(t=>t.stop());return;}stream=pendingStream;$('camera').srcObject=stream;await $('camera').play();if(request!==cameraEpoch||document.hidden||step!=='camera'){if(stream===pendingStream)stopCamera();else pendingStream.getTracks().forEach(t=>t.stop());return;}if(!$('camera').videoWidth)await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('카메라 영상을 준비하지 못했어요.')),7000);$('camera').onloadeddata=()=>{clearTimeout(timer);resolve();};});if(request!==cameraEpoch||document.hidden||step!=='camera'){if(stream===pendingStream)stopCamera();else pendingStream.getTracks().forEach(t=>t.stop());return;}$('camera').style.transform=facing==='user'?'scaleX(-1)':'none';$('camera').hidden=false;renderControls();}catch(e){if(request!==cameraEpoch)return;stopCamera();const known={NotAllowedError:'카메라 권한을 허용하거나 사진 불러오기를 이용해 주세요.',NotFoundError:'사용할 수 있는 카메라가 없어요. 사진 불러오기를 이용해 주세요.',NotReadableError:'다른 앱이 카메라를 사용 중일 수 있어요. 다른 앱을 닫고 다시 켜 주세요.'};throw Error(known[e.name]||e.message);}}
let audio;
function beep(){if(!settings.sound)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.connect(gain);gain.connect(audio.destination);gain.gain.value=.035;osc.frequency.value=700;osc.start();osc.stop(audio.currentTime+.1);}catch{}}
const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function countdown(epoch){$('countdown').hidden=false;try{for(let i=settings.timer;i>0;i--){if(epoch!==cancelEpoch||!stream)throw new DOMException('촬영 중단','AbortError');$('countdown').textContent=i;beep();await delay(1000);}if(epoch!==cancelEpoch||!stream)throw new DOMException('촬영 중단','AbortError');}finally{$('countdown').hidden=true;}}
function captureCanvas(){const v=$('camera'),c=document.createElement('canvas');const w=v.videoWidth,h=v.videoHeight;if(!w||!h)throw Error('카메라가 준비된 뒤 다시 찍어 주세요.');const sw=Math.min(w,h*4/3),sh=Math.min(h,w*3/4),scale=Math.min(1,1600/sw);c.width=Math.round(sw*scale);c.height=Math.round(sh*scale);const ctx=c.getContext('2d');if(facing==='user'){ctx.translate(c.width,0);ctx.scale(-1,1);}ctx.drawImage(v,(w-sw)/2,(h-sh)/2,sw,sh,0,0,c.width,c.height);return c;}
async function processSource(source,{index=active,target=replaceTarget,original=false,epoch=cancelEpoch,mode=sourceMode}={}){let result=null,sourceOnly=original;while(!sourceOnly){try{setBusy(true);const m=await segmentPhoto(source);if(epoch!==cancelEpoch)return false;const image=makeCutout(source,m.mask,m.w,m.h);result={image,w:image.width,h:image.height,source,mask:m.mask,mw:m.w,mh:m.h};break;}catch(e){if(epoch!==cancelEpoch)return false;setBusy(false);const choice=await errorChoice(e.message);if(choice==='cancel')return false;if(choice==='original'){sourceOnly=true;break;}resetSegmenter();}}
if(epoch!==cancelEpoch)return false;if(sourceOnly)result={image:source,w:source.width,h:source.height,source};const c=project.cuts[index];if(!target&&mode!=='replace-cut'&&personItems(c).length>=3){setBusy(false);throw Error('한 컷에는 인물 3개까지 넣을 수 있어요. 기존 인물을 선택해 바꾸거나 다른 컷을 골라 주세요.');}record();const id=uid();assets.set(id,result);const old=target&&c.items.find(i=>i.id===target);if(mode==='replace-cut')c.items=[];else if(old)c.items=c.items.filter(i=>i.id!==target);const newItem=addItem(c,id,result.w,result.h);if(old){newItem.x=old.x;newItem.y=old.y;newItem.rotation=old.rotation;newItem.scale=old.scale*(assets.get(old.assetId)?.w||result.w)/result.w;}c.original=sourceOnly;selected=newItem.id;active=index;replaceTarget=null;sourceMode='append';setBusy(false);cleanAssets();return true;}
function reviewCapture(source){return new Promise(resolve=>{const d=$('capture-review'),c=$('capture-review-image');c.width=source.width;c.height=source.height;c.getContext('2d').drawImage(source,0,0);let done=false;const finish=value=>{if(done)return;done=true;d.close();d.removeEventListener('cancel',cancel);c.width=c.height=0;resolve(value);};const cancel=e=>{e.preventDefault();finish(false);};$('capture-retake').onclick=()=>finish(false);$('capture-use').onclick=()=>finish(true);d.addEventListener('cancel',cancel);d.showModal();});}
async function shoot(auto=false){if(busy||running||!stream)return;const epoch=++cancelEpoch;let indices=auto?project.cuts.slice(0,project.count||4).map((c,i)=>personItems(c).length?null:i).filter(i=>i!==null):[active];if(auto&&!indices.length){message('네 컷이 모두 찼어요. 바꿀 컷을 고르고 다시 찍기를 눌러 주세요.');return;}if(!auto&&!replaceTarget&&personItems(cut()).length>=3){message('이 컷의 인물을 선택해 다시 찍거나 다른 컷을 골라 주세요.');return;}running=true;renderControls();try{for(const index of indices){active=index;await render();await countdown(epoch);let source=captureCanvas();beep();if(!auto){while(!await reviewCapture(source)){if(epoch!==cancelEpoch||!stream)return;await countdown(epoch);source=captureCanvas();beep();}if(epoch!==cancelEpoch)return;}$('camera').hidden=true;const success=await processSource(source,{index,epoch});if(epoch!==cancelEpoch)break;if(!success)break;if(auto){$('camera').hidden=false;await delay(500);}}}finally{running=false;setBusy(false);$('countdown').hidden=true;stopCamera();step=isComplete(project)?'finish':'edit';render();}}
on('start-camera','click',safe(startCamera));on('stop-camera','click',()=>stopCamera());on('switch-camera','click',safe(async()=>{facing=facing==='user'?'environment':'user';await startCamera();}));on('capture','click',safe(()=>shoot()));on('auto-capture','click',safe(()=>shoot(true)));on('stop-capture','click',()=>{cancelEpoch++;running=false;resetSegmenter();setBusy(false);stopCamera();message('촬영을 중단했어요. 완성된 컷은 남겨 두었어요.');});
function selectImports(files){return new Promise(resolve=>{const d=$('import-dialog'),list=$('import-list');let done=false;function show(){list.replaceChildren();files.forEach((file,i)=>{const row=document.createElement('div');row.className='import-row';const name=document.createElement('span');name.textContent=(i+1)+'. '+file.name;row.append(name);for(const [label,delta] of [['위로',-1],['아래로',1]]){const b=document.createElement('button');b.type='button';b.className='button compact';b.textContent=label;b.disabled=i+delta<0||i+delta>=files.length;b.onclick=()=>{[files[i],files[i+delta]]=[files[i+delta],files[i]];show();};row.append(b);}list.append(row);});}show();$('import-mode').hidden=files.length!==1||!personItems(cut()).length;function finish(ok){if(done)return;done=true;d.close();resolve(ok?{files,mode:document.querySelector('input[name="import-mode"]:checked').value}:null);}$('import-cancel').onclick=()=>finish(false);$('import-confirm').onclick=()=>finish(true);d.oncancel=e=>{e.preventDefault();finish(false);};d.querySelector('[data-close]').onclick=()=>finish(false);d.showModal();});}
on('photo-input','change',safe(async e=>{const files=[...e.target.files];e.target.value='';if(!files.length)return;if(files.length>4){message('한 번에 사진 4장까지 선택할 수 있어요.');return;}const selection=await selectImports(files);if(!selection)return;const epoch=++cancelEpoch;stopCamera();const start=active;try{for(const file of selection.files){const index=selection.files.length===1?active:project.cuts.slice(0,project.count||4).map((c,j)=>({c,j})).find(({c,j})=>j>=start&&!personItems(c).length)?.j;if(index===undefined){message('빈 컷이 부족해 남은 사진은 넣지 않았어요.');break;}const choice=selection.files.length===1?selection.mode:'append';const target=choice==='replace-person'?(item()?.kind==='person'?item().id:personItems(project.cuts[index])[0]?.id):null;if(choice==='append'&&personItems(project.cuts[index]).length>=3)throw Error('인물은 컷마다 3개까지 넣을 수 있어요.');setBusy(true,'사진을 준비하고 있어요');const source=await readPhoto(file);if(epoch!==cancelEpoch)break;const ok=await processSource(source,{index,target,mode:choice==='replace-cut'?'replace-cut':'append',original:$('original-import').checked,epoch});if(!ok)break;step='edit';}}finally{setBusy(false);if(isComplete(project))step='finish';render();}}));
document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>setStep(b.dataset.step));on('go-camera','click',()=>{sourceMode='append';replaceTarget=null;setStep('camera');});on('show-finish','click',()=>setStep('finish'));on('next-cut','click',()=>{if(active+1>=(project.count||4)){setStep('finish');return;}active++;setStep(personItems(cut()).length?'edit':'background');});
on('add-person','click',()=>{replaceTarget=null;sourceMode='append';setStep('camera');});on('retake','click',()=>{const current=item()?.kind==='person'?item():personItems(cut())[0];if(!current)return;replaceTarget=current.id;sourceMode='append';setStep('camera');message('새 사진을 확정하기 전까지 기존 인물은 유지돼요.');});
